frame.store("_worth_it", { let __signature_942 = Signature { name: "_worth_it".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_944 = Value::dict(); __attrs_944.dict_set(Value::from("__doc__"), Value::from("A view on the one work the line names.\n\n    People ask this about something they are about to spend an evening on, so the answer is a\n    yes or a no with the reason, never a list of other things: \"is it worth watching the wire\"\n    is not \"what should I watch\". Only a work in the table gets here; one nobody here knows is\n    the other entry's business, and a report of something already seen wants to talk.\n    "))?; __attrs_944.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_945 = Value::dict(); __attrs_944.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_941 = Frame::module(frame.globals.clone()); let mut __function_943 = NativeFunction::qualified_with_origin("_worth_it".into(), "_worth_it".into(), "bot.knowledge.entertainment".into(), __attrs_944, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/entertainment.py", first: 2481, last: 2493, qualname: "_worth_it" }, closure: __closure_941.clone(), freevars: vec![] }, move |rt, args| __py_42::_worth_it(rt, __closure_941.clone(), &__signature_942, args)); __function_943 })?;
frame.store("_worth_it_unnamed", { let __signature_947 = Signature { name: "_worth_it_unnamed".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_949 = Value::dict(); __attrs_949.dict_set(Value::from("__doc__"), Value::from("An honest line about a work the table does not know, or about one only called \"it\".\n\n    The table cannot hold every film and book, and inventing a verdict is worse than saying\n    which of the two this is, so the line names the work when the ask named it and always\n    offers a way to judge it. A pick of anything (\"whats a good film\"), a gift, tonight's\n    telly and a question about whether reading is good for you all have their own entries.\n    "))?; __attrs_949.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_950 = Value::dict(); __attrs_949.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_946 = Frame::module(frame.globals.clone()); let mut __function_948 = NativeFunction::qualified_with_origin("_worth_it_unnamed".into(), "_worth_it_unnamed".into(), "bot.knowledge.entertainment".into(), __attrs_949, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/entertainment.py", first: 2496, last: 2517, qualname: "_worth_it_unnamed" }, closure: __closure_946.clone(), freevars: vec![] }, move |rt, args| __py_43::_worth_it_unnamed(rt, __closure_946.clone(), &__signature_947, args)); __function_948 })?;
frame.store("_named_work", { let __signature_952 = Signature { name: "_named_work".into(), positional: vec!["text".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_954 = Value::dict(); __attrs_954.dict_set(Value::from("__doc__"), Value::from("The work a judging line names, as it should be written, or \"\".\n\n    The title sits before the ask in one shape (\"is oppenheimer worth watching\") and after the\n    verb in the other (\"should i watch the wire\"), so both are read; the words that make the\n    line an ask (worth, good, any good) and the place and time words are cut off, because\n    \"is oppenheimer worth watching\" would otherwise name a film called *Is Oppenheimer Worth\n    Watching*.\n    "))?; __attrs_954.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_955 = Value::dict(); __attrs_954.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_951 = Frame::module(frame.globals.clone()); let mut __function_953 = NativeFunction::qualified_with_origin("_named_work".into(), "_named_work".into(), "bot.knowledge.entertainment".into(), __attrs_954, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/entertainment.py", first: 2521, last: 2550, qualname: "_named_work" }, closure: __closure_951.clone(), freevars: vec![] }, move |rt, args| __py_44::_named_work(rt, __closure_951.clone(), &__signature_952, args)); __function_953 })?;
frame.store("_table_pick", { let __signature_957 = Signature { name: "_table_pick".into(), positional: vec!["text".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_959 = Value::dict(); __attrs_959.dict_set(Value::from("__doc__"), Value::from("The pick for the title this line really names, or \"\" for a line that names none of ours.\n\n    Both the pick-that-follows row and the film-like row read the same table, so both ask this\n    one question: a title that is also a plain phrase has to be a work in the line as well.\n    "))?; __attrs_959.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_960 = Value::dict(); __attrs_959.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_956 = Frame::module(frame.globals.clone()); let mut __function_958 = NativeFunction::qualified_with_origin("_table_pick".into(), "_table_pick".into(), "bot.knowledge.entertainment".into(), __attrs_959, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/entertainment.py", first: 2553, last: 2572, qualname: "_table_pick" }, closure: __closure_956.clone(), freevars: vec![] }, move |rt, args| __py_45::_table_pick(rt, __closure_956.clone(), &__signature_957, args)); __function_958 })?;
