frame.store("_a_judged_work_named", { let __signature_1033 = Signature { name: "_a_judged_work_named".into(), positional: vec!["understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1035 = Value::dict(); __attrs_1035.dict_set(Value::from("__doc__"), Value::from("True when the line names a work of the table and asks for a view on it.\n\n    \"is dune a good book\" names *Dune* and carries a judgement, so it is a question about that\n    book and the verdict row answers it. The subject row matched it as well - \"book\" plus \"good\"\n    - and won on its bias, so `lookup.find` handed back a row whose reply then stood down for\n    want of a subject, and the answer underneath was correct while the row that gave it was not.\n    A line that names a work *and* judges it is never a request for a book on a subject, so this\n    row stands down instead. \"recommend a book about the office\" carries no judgement word and\n    is not touched.\n    "))?; __attrs_1035.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_1036 = Value::dict(); __attrs_1035.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1032 = Frame::module(frame.globals.clone()); let mut __function_1034 = NativeFunction::qualified_with_origin("_a_judged_work_named".into(), "_a_judged_work_named".into(), "bot.knowledge.entertainment".into(), __attrs_1035, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/entertainment.py", first: 2870, last: 2885, qualname: "_a_judged_work_named" }, closure: __closure_1032.clone(), freevars: vec![] }, move |rt, args| __py_52::_a_judged_work_named(rt, __closure_1032.clone(), &__signature_1033, args)); __function_1034 })?;
