let __v_6541 = pyrt::literals::decode("{\"$dict\":[[\"violin\",\"A violin has four strings, tuned G, D, A and E from the lowest up.\"],[\"fiddle\",\"A fiddle is a violin, so four strings: G, D, A and E from the lowest up.\"],[\"viola\",\"A viola has four strings, C, G, D and A - a fifth lower than a violin.\"],[\"cello\",\"A cello has four strings, C, G, D and A, an octave below a viola.\"],[\"double bass\",\"A double bass has four strings, E, A, D and G, and some have a fifth.\"],[\"bass\",\"A bass guitar has four strings, E, A, D and G - the same notes as the bottom four of a guitar, an octave lower.\"],[\"guitar\",\"A guitar has six strings, E, A, D, G, B and E from the thickest up. A 12-string guitar has twelve, in six pairs.\"],[\"ukulele\",\"A ukulele has four strings, G, C, E and A.\"],[\"banjo\",\"A five-string banjo has five, with the short fifth string partway up the neck.\"],[\"mandolin\",\"A mandolin has eight strings in four pairs, tuned like a violin: G, D, A, E.\"],[\"piano\",\"A piano has 88 keys: 52 white and 36 black, seven and a bit octaves from A0 to C8.\"],[\"keyboard\",\"A full-size piano keyboard has 88 keys; a smaller synth or starter keyboard usually has 61 or 49.\"],[\"harp\",\"A concert harp has 47 strings, six and a half octaves.\"]]}")?;
